/// Uses IMemoryCache with sliding expiration.
/// </summary>
public async Task<Consumer14Data> GetCachedConsumer14Async(string key)
{
    var cacheKey = $"Consumer14_{key}";

    if (_cache.TryGetValue(cacheKey, out Consumer14Data cached))
